    /** "id|type|category|chinese|korean" rows, in table order. */
    public static String[] rows() {
        return RAW;
    }

    /** ETB_Item_TypeMain for an item id, or 0 when the id is unknown. */
    public static int typeOf(int id) {
        for (String r : RAW) {
            int bar = r.indexOf('|');
            if (bar <= 0) continue;
            try {
                if (Integer.parseInt(r.substring(0, bar)) == id) {
                    int bar2 = r.indexOf('|', bar + 1);
                    return Integer.parseInt(r.substring(bar + 1, bar2));
                }
            } catch (NumberFormatException ignored) { }
        }
        return 0;
    }
